#!/bin/sh
# Builds SG004_DOOM_GAME.bin for the FNIRSI bootloader (app base 0x08005800, at most 0x6A000 bytes).
# clang for everything (soft float, Cortex-M4), linked with arm-none-eabi-ld, libgcc from arm-none-eabi-gcc for the 64-bit helpers.
#   GEN=<dir>   tables generated by tools/conv for the data pack that will be on the NOR (gen/info.h, ...)
#   OUT=<dir>   build directory (default build/)
#   SG_ARGS='"doom","-warp","1","1"'  engine command line (sg_args.h)
set -e
export PATH="/c/msys64/ucrt64/bin:/c/msys64/usr/bin:$PATH"
HERE=$(cd "$(dirname "$0")" && pwd)
D=$HERE/../dmc100
GEN=${GEN:?set GEN to the generated tables of the data pack}
OUT=${OUT:-$HERE/build}
mkdir -p "$OUT/obj"
cd "$D"

DEFS="-DDMC_FW -DPLAT_HOST -DDMC_HASHORDER -DDMC_SINE_L1 -DSG_NO_INTERMISSION -DSG_MAXEVENTS=32"
# SG_ARGS: C initialiser of the command line, for example SG_ARGS='"doom","-warp","1","1","-skill","3"'
echo "#define SG_ARGS ${SG_ARGS:-\"doom\"}" > "$OUT/sg_args.h"
ARCH="--target=thumbv7em-none-eabi -mcpu=cortex-m4 -mthumb -mfloat-abi=soft"
INC="-I$OUT -I$HERE -Iengine/stub/include -Iengine -Iport/data -Iport/render -Iport/obj -Iport/math -Iplatform -Iport/game -Iport/ovl -I$GEN"
CF="$ARCH -Os -ffunction-sections -fdata-sections -ffreestanding -fno-common -fwrapv -fsigned-char -std=gnu11 -w $DEFS $INC"

# upstream: engine, data layer (own fat12 replacement), renderer, object store, front end glue
SRCS=""
for f in engine/*.c; do
  case $f in engine/w_wad.c|engine/w_file.c|engine/am_map.c|engine/z_zone.c) continue;; esac
  SRCS="$SRCS $f"
done
for f in port/data/*.c; do
  case $f in port/data/fat12.c|port/data/fat_write.c) continue;; esac
  SRCS="$SRCS $f"
done
SRCS="$SRCS $(ls port/render/*.c port/obj/*.c) port/math/trig.c"
SRCS="$SRCS port/game/fe_glue.c port/game/l_menu.c port/game/l_wi.c port/game/l_finale.c port/game/libc_dmc.c port/ovl/ovl.c port/ovl/ovl_file.c platform/rt.c platform/text.c platform/font8x8.c"
# own platform layer
OWN="startup.c clock.c fault.c sg_lcd.c sg_nor.c sg_fat.c sg_input.c sg_video.c sg_system.c sg_glue.c sg_main.c"

OBJS=""
for f in $SRCS; do
  o="$OUT/obj/$(echo "$f" | tr '/' '_').o"
  OBJS="$OBJS $o"
  if [ ! -f "$o" ] || [ "$f" -nt "$o" ]; then
    clang $CF -c "$f" -o "$o" || { echo "FAILED: $f" >&2; exit 1; }
  fi
done
for f in $OWN; do
  o="$OUT/obj/own_$f.o"
  OBJS="$OBJS $o"
  clang $CF -Wall -Wno-unused-parameter -c "$HERE/$f" -o "$o" || { echo "FAILED: $f" >&2; exit 1; }
done
for g in info colormap trig_tables view; do
  o="$OUT/obj/gen_$g.o"
  OBJS="$OBJS $o"
  clang $CF -c "$GEN/$g.c" -o "$o"
done

LIBGCC=$(arm-none-eabi-gcc -mcpu=cortex-m4 -mthumb -mfloat-abi=soft -print-libgcc-file-name)
arm-none-eabi-ld -T "$HERE/link.ld" --gc-sections -Map="$OUT/doom.map" --allow-multiple-definition \
    -o "$OUT/doom.elf" $OBJS "$LIBGCC"
llvm-objcopy -O binary "$OUT/doom.elf" "$OUT/SG004_DOOM_GAME.bin"
llvm-size "$OUT/doom.elf"
size=$(stat -c %s "$OUT/SG004_DOOM_GAME.bin")
echo "bin: $size of $((0x6A000)) bytes"

# Safety gate: this firmware must not write flash, the NOR or the option bytes.
if grep -n -E "FLASH_KEYR|FLASH_CR|45670123|CDEF89AB|0x1FFFF800|xfer\((0x02|0x20|0x06|0xC7|0x60|0xD8|0x52|0x01)\)" \
        "$HERE"/sg_*.c "$HERE"/clock.c "$HERE"/fault.c "$HERE"/startup.c; then
  echo "SAFETY GATE: flash write/erase code found in the sources" >&2
  rm -f "$OUT/SG004_DOOM_GAME.bin"
  exit 1
fi
echo "safety gate ok: no flash/NOR write or erase code in our sources"
